// Every trashed message of one conversation. Permanent deletion follows the
// same conversation semantics as the rest of the list: the trash row stands
// for the exchange, so confirming deletes the exchange. Only trashed rows —
// a live message of the same thread is not swept up by this.
//
// **按信箱限定**（00044 的口径）。这一句后面接的是**永久删除**加一条发给
// 邮件服务器的删除指令，所以「同一条会话也落在另一个信箱里」的那份必须
// 留下。调用方手上有 account_id：进这条路之前先 GetInbound 拿了那一行。
func (q *Queries) ListThreadForPurge(ctx context.Context, arg ListThreadForPurgeParams) ([]ListThreadForPurgeRow, error) {
	rows, err := q.db.Query(ctx, listThreadForPurge,
		arg.TenantID,
		arg.OwnerID,
		arg.AccountID,
		arg.ThreadKey,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListThreadForPurgeRow
	for rows.Next() {
		var i ListThreadForPurgeRow
		if err := rows.Scan(
			&i.ID,
			&i.RawKey,
			&i.AccountID,
			&i.Folder,
			&i.ImapUid,
			&i.MessageID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listThreadsByView = `-- name: ListThreadsByView :many
SELECT m.id, m.from_email, m.from_name, m.subject, m.snippet, m.thread_key,
       (NOT t.any_unread)::boolean     AS is_read,
       t.any_starred::boolean          AS is_starred,
       t.any_attachment::boolean       AS has_attachments,
       m.received_at, m.sent_at,
       t.msg_count::int                AS thread_count
FROM mail_thread_view t
JOIN email_inbound m ON m.tenant_id = t.tenant_id AND m.id = t.last_id
WHERE t.tenant_id = $1::bigint
  AND t.owner_id = $2::bigint
  -- 不传 = 全部信箱，走 00034 那条旧索引；传了走
  -- mail_thread_view_account_list_idx（00044）。左侧切换器上线前，前端
  -- 什么都不传，所以两条索引这一版都还要在。
  AND ($3::bigint IS NULL
       OR t.account_id = $3::bigint)
  AND t.view = $4::text
  -- Row comparison, so ties on the timestamp fall back to the id and no two
  -- conversations can ever occupy the same cursor position.
  AND ($5::timestamptz IS NULL
       OR (t.last_at, t.last_id) < ($5::timestamptz,
                                    $6::bigint))
ORDER BY t.last_at DESC, t.last_id DESC
LIMIT $7::int
`

type ListThreadsByViewParams struct {
	TenantID  int64
	OwnerID   int64
	AccountID *int64
	View      string
	CursorAt  pgtype.Timestamptz
	CursorID  int64
	RowLimit  int32
}

type ListThreadsByViewRow struct {
	ID             int64
	FromEmail      string
	FromName       string
	Subject        string
	Snippet        string
	ThreadKey      string
	IsRead         bool
	IsStarred      bool
	HasAttachments bool
	ReceivedAt     pgtype.Timestamptz
	SentAt         pgtype.Timestamptz
	ThreadCount    int32
}

// The mailbox list, read from the rows it shows.
//
// Replaces a CTE that materialised every message the owner could see, sorted
// it by conversation, ran four window functions over it and took the newest
// twenty-five off the end. That work was proportional to the whole mailbox on
// every page load - 70 ms and a disk-spilling sort for a heavy user - because
// a conversation's count and unread badge are facts about all of its messages
// and no index can compute them.
//
// mail_thread_view holds those facts already, maintained by trigger. See
// migration 00034.
//
// Keyset, not OFFSET: the page starts strictly after the last row of the
// previous one, so mail arriving mid-read cannot push a conversation across a
// page boundary and make it appear twice or not at all, and page 50 costs the
// same as page 2.
func (q *Queries) ListThreadsByView(ctx context.Context, arg ListThreadsByViewParams) ([]ListThreadsByViewRow, error) {
	rows, err := q.db.Query(ctx, listThreadsByView,
		arg.TenantID,
		arg.OwnerID,
		arg.AccountID,
		arg.View,
		arg.CursorAt,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListThreadsByViewRow
	for rows.Next() {
		var i ListThreadsByViewRow
		if err := rows.Scan(
			&i.ID,
			&i.FromEmail,
			&i.FromName,
			&i.Subject,
			&i.Snippet,
			&i.ThreadKey,
			&i.IsRead,
			&i.IsStarred,
			&i.HasAttachments,
			&i.ReceivedAt,
			&i.SentAt,
			&i.ThreadCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listThreadsByViewSorted = `-- name: ListThreadsByViewSorted :many
SELECT x.id, x.from_email, x.from_name, x.subject, x.snippet, x.thread_key,
       x.is_read, x.is_starred, x.has_attachments, x.received_at, x.sent_at,
       x.thread_count, x.raw_size, x.sort_key
FROM (
    SELECT m.id, m.from_email, m.from_name, m.subject, m.snippet, m.thread_key,
           (NOT t.any_unread)::boolean     AS is_read,
           t.any_starred::boolean          AS is_starred,
           t.any_attachment::boolean       AS has_attachments,
           m.received_at, m.sent_at,
           t.msg_count::int                AS thread_count,
           m.raw_size,
           (CASE $1::text
              WHEN 'from'    THEN lower(coalesce(nullif(m.from_name, ''), m.from_email))
              WHEN 'subject' THEN lower(m.subject)
              WHEN 'size'    THEN lpad(m.raw_size::text, 20, '0')
              ELSE to_char(t.last_at AT TIME ZONE 'UTC', 'YYYYMMDDHH24MISSUS')
            END)::text                    AS sort_key
    FROM mail_thread_view t
    JOIN email_inbound m ON m.tenant_id = t.tenant_id AND m.id = t.last_id
    WHERE t.tenant_id = $2::bigint
      AND t.owner_id = $3::bigint
      AND ($4::bigint IS NULL
           OR t.account_id = $4::bigint)
      AND t.view = $5::text
) x
WHERE ($6::text IS NULL
       OR CASE WHEN $7::text = 'asc'
               THEN (x.sort_key, x.id) > ($6::text, $8::bigint)
               ELSE (x.sort_key, x.id) < ($6::text, $8::bigint)
          END)
ORDER BY CASE WHEN $7::text = 'asc' THEN x.sort_key END ASC,
         CASE WHEN $7::text = 'asc' THEN x.id END ASC,
         x.sort_key DESC, x.id DESC
LIMIT $9::int
`

type ListThreadsByViewSortedParams struct {
	SortBy    string
	TenantID  int64
	OwnerID   int64
	AccountID *int64
	View      string
	CursorKey *string
	SortDir   string
	CursorID  int64
	RowLimit  int32
}

type ListThreadsByViewSortedRow struct {
	ID             int64
	FromEmail      string
	FromName       string
	Subject        string
	Snippet        string
	ThreadKey      string
	IsRead         bool
	IsStarred      bool
	HasAttachments bool
	ReceivedAt     pgtype.Timestamptz
	SentAt         pgtype.Timestamptz
	ThreadCount    int32
	RawSize        int64
	SortKey        string
}

// 同一份列表，按人点的那一列排。
//
// 和 ListThreadsByView 分成两条而不是合成一条：上面那条靠索引顺序直接读出
// 前二十五行，是一天到晚都在走的路；这一条要把整个箱的会话拿出来排一遍，
// 只在有人点了排序栏时才走。把 CASE 塞进上面那条的 ORDER BY 会让索引顺序
// 用不上，等于为一个偶尔用的功能给常走的路加税。
//
// **排序键统一成一段文本。** 发件人和主题本来就是文本；大小补零到 20 位，
// 时间格式化成 UTC 的 20 位数字串——两者按字典序比就是按数值比。这样做的
// 好处是游标只有一种形状：(sort_key, id)，不用给每一列各写一套「上一页
// 停在哪」的比较。lower() 是为了让大小写不同的同一个名字排在一起，而不是
// 看数据库的排序规则脸色。
//
// 会话的「发件人」「主题」「大小」都是**最后一封**的——列表上那一行显示的
// 就是它，排的也是它。一条会话里有十封信，大小按最后那封算。
//
// 方向靠两组 CASE：asc 时前两个键生效、后两个键在完全相同的 (sort_key, id)
// 上才轮得到（不可能相同，所以无害）；desc 时前两个键全是 NULL，等价于
// 只按后两个排。
// 上一页停在哪：asc 往大了走，desc 往小了走。id 兜底，两条会话不可能占同一个位置。
func (q *Queries) ListThreadsByViewSorted(ctx context.Context, arg ListThreadsByViewSortedParams) ([]ListThreadsByViewSortedRow, error) {
	rows, err := q.db.Query(ctx, listThreadsByViewSorted,
		arg.SortBy,
		arg.TenantID,
		arg.OwnerID,
		arg.AccountID,
		arg.View,
		arg.CursorKey,
		arg.SortDir,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListThreadsByViewSortedRow
	for rows.Next() {
		var i ListThreadsByViewSortedRow
		if err := rows.Scan(
			&i.ID,
			&i.FromEmail,
			&i.FromName,
			&i.Subject,
			&i.Snippet,
			&i.ThreadKey,
			&i.IsRead,
			&i.IsStarred,
			&i.HasAttachments,
			&i.ReceivedAt,
			&i.SentAt,
			&i.ThreadCount,
			&i.RawSize,
			&i.SortKey,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

